// Some portions generated by Co-Pilot
import {
  act,
  fireEvent,
  render,
  screen,
  waitFor,
  within,
} from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import DownloadTrendsPage from "../trends-client";

vi.mock("next-intl", async () => {
  const actual = await vi.importActual<typeof import("next-intl")>("next-intl");
  const messages = (await import("@/../locales/en.json")).default;
  return {
    ...actual,
    useLocale: () => "en",
    useTranslations: (namespace: "ModernPages.stats" | "ModernPages.common") =>
      actual.createTranslator({ locale: "en", messages, namespace }),
  };
});

vi.mock("@/utils/fetchAvailableReleases", () => ({
  fetchAvailableReleases: async () => ({ available_releases: [21, 25] }),
}));
vi.mock("@/components/Dashboard/LineChart", () => ({
  default: (props: object) => (
    <output data-testid="line-chart">{JSON.stringify(props)}</output>
  ),
}));
vi.mock("@/components/Dashboard/BarChart", () => ({
  default: (props: object) => (
    <output data-testid="bar-chart">{JSON.stringify(props)}</output>
  ),
}));

afterEach(() => vi.unstubAllGlobals());

function renderTrends() {
  const fetchMock = vi.fn(async (url: string) => ({
    ok: true,
    json: async () =>
      url.includes("/monthly/")
        ? [{ month: "2026-10", monthly: 5, total: 20 }]
        : [{ date: "2026-10-01", daily: 2, total: 10 }],
  }));
  vi.stubGlobal("fetch", fetchMock);
  render(<DownloadTrendsPage />);
  return fetchMock;
}

describe("Download trends controls", () => {
  it("renders both charts", async () => {
    renderTrends();
    expect(await screen.findByTestId("line-chart")).toHaveTextContent(
      '"data":[2]',
    );
    expect(screen.getByTestId("bar-chart")).toHaveTextContent('"Oct 2026":5');
  });

  it("preserves source and version filtering", async () => {
    const fetchMock = renderTrends();
    await screen.findByTestId("line-chart");
    const series = await screen.findByRole("group", { name: "Series 1" });
    fireEvent.click(within(series).getByRole("radio", { name: "GitHub" }));
    fireEvent.change(
      within(series).getByRole("combobox", { name: "JDK version" }),
      {
        target: { value: "25" },
      },
    );
    await waitFor(() =>
      expect(fetchMock).toHaveBeenCalledWith(
        expect.stringContaining("source=github&feature_version=25"),
      ),
    );
  });

  it("updates the range using the keyboard and keeps visibility controls labelled", async () => {
    const fetchMock = renderTrends();
    await screen.findByTestId("line-chart");
    const series = await screen.findByRole("group", { name: "Series 1" });
    expect(
      within(series).getByRole("checkbox", { name: "Show series" }),
    ).toBeChecked();
    const slider = screen.getByRole("slider", { name: "Days" });
    fireEvent.change(slider, { target: { value: "60" } });
    fireEvent.keyUp(slider, { key: "ArrowRight" });
    await waitFor(() =>
      expect(fetchMock).toHaveBeenCalledWith(
        expect.stringContaining("days=60"),
      ),
    );
  });

  it("keeps the chart slots and controls mounted throughout loading", async () => {
    const ready = Promise.withResolvers<void>();
    vi.stubGlobal(
      "fetch",
      vi.fn(async () => {
        await ready.promise;
        return { ok: true, json: async () => [] };
      }),
    );
    const { container } = render(<DownloadTrendsPage />);
    const dashboard = container.firstElementChild;
    const chartSlots = container.querySelectorAll(".h-\\[400px\\]");
    const controls = screen.getAllByRole("combobox", { name: "JDK version" });
    expect(dashboard).toHaveAttribute("aria-busy", "true");
    expect(chartSlots).toHaveLength(2);
    expect(screen.getByText(/^Loading/)).toBeInTheDocument();
    controls.forEach((control) => expect(control).toBeDisabled());

    await act(async () => ready.resolve());
    await screen.findByTestId("line-chart");
    expect(container.firstElementChild).toBe(dashboard);
    expect(dashboard).toHaveAttribute("aria-busy", "false");
    expect(container.querySelectorAll(".h-\\[400px\\]")[0]).toBe(chartSlots[0]);
    screen
      .getAllByRole("combobox", { name: "JDK version" })
      .forEach((control, index) => {
        expect(control).toBe(controls[index]);
        expect(control).toBeEnabled();
      });
  });
});
